CREATE OR REPLACE FUNCTION calculate_reviewer_denial_rate(p_reviewer_id INTEGER)
RETURNS NUMERIC(5,2)
LANGUAGE plpgsql
AS $$
DECLARE
  v_total_count INTEGER;
  v_denied_count INTEGER;
  v_denial_rate NUMERIC(5,2);
BEGIN
  SELECT COUNT(*) INTO v_total_count
  FROM diagnosis_reviews
  WHERE reviewer_id = p_reviewer_id;

  IF v_total_count = 0 THEN
    RETURN 0.00;
  END IF;

  SELECT COUNT(*) INTO v_denied_count
  FROM diagnosis_reviews
  WHERE reviewer_id = p_reviewer_id AND denial_status = 'DENIED';

  v_denial_rate := ROUND((v_denied_count::NUMERIC / v_total_count::NUMERIC) * 100, 2);

  RETURN v_denial_rate;
END;
$$;

SELECT calculate_reviewer_denial_rate(1) AS denial_rate;
